<template>
  <div class="box">
    <!-- 左侧数字0 -->
    <div class="scale-number left">0</div>
    <!-- 右侧数字100 -->
    <div class="scale-number right">100</div>
    <div class="scale-container">
      <!-- 横条 -->
      <div class="scale-bar" ref="scaleBar"></div>
      <!-- 第一个标志 -->
      <div class="marker" :style="{ left: marker1Position + '%' }" @mousedown="startDragging(1, $event)">
        {{ marker1Value }}
      </div>
      <!-- 第二个标志 -->
      <div class="marker2" :style="{ left: marker2Position + '%' }" @mousedown="startDragging(2, $event)">
        {{ marker2Value }}
      </div>
    </div>
  </div>
</template>
  
  <script>
export default {
  name: 'ScaleSlider',
  props: {
    initialMarker1Value: {
      type: Number,
      required: true,
    },
    initialMarker2Value: {
      type: Number,
      required: true,
    },
  },
  watch: {
    initialMarker1Value(newVal, oldVal) {
      this.marker1Value= oldVal
      this.marker1Position= oldVal
    },
    initialMarker2Value(newVal, oldVal) {
      this.marker2Value= oldVal
      this.marker2Position= oldVal
    },
  },
  data() {
    return {
      isDragging: false,
      currentMarker: null,
      marker1Value: this.initialMarker1Value,
      marker1Position: this.initialMarker1Value,
      marker2Value: this.initialMarker2Value,
      marker2Position: this.initialMarker2Value,
    };
  },
  mounted() {

  },
  methods: {
    startDragging(marker, event) {
      this.isDragging = true;
      this.currentMarker = marker;
      window.addEventListener('mousemove', this.onDrag);
      window.addEventListener('mouseup', this.stopDragging);
    },
    onDrag(event) {
      if (this.isDragging) {
        console.log(this.$refs.scaleBar.getBoundingClientRect())
        console.log(this.$refs.scaleBar)
        const scaleBar = this.$refs.scaleBar.getBoundingClientRect();
        let newLeft = ((event.clientX - scaleBar.left) / scaleBar.width) * 100;

        // Ensure the new position stays within 0% to 100%
        if (newLeft < 0) newLeft = 0;
        if (newLeft > 100) newLeft = 100;

        // Ensure the markers do not overlap
        if (this.currentMarker === 1) {
          if (newLeft > this.marker2Position) newLeft = this.marker2Position;
          this.marker1Position = newLeft;
          this.marker1Value = Math.round(newLeft);
          this.$emit('updateMarkers', { marker1Value: this.marker1Value, marker2Value: this.marker2Value });
        } else if (this.currentMarker === 2) {
          if (newLeft < this.marker1Position) newLeft = this.marker1Position;
          this.marker2Position = newLeft;
          this.marker2Value = Math.round(newLeft);
          this.$emit('updateMarkers', { marker1Value: this.marker1Value, marker2Value: this.marker2Value });
        }
      }
    },
    stopDragging() {
      this.isDragging = false;
      this.currentMarker = null;
      window.removeEventListener('mousemove', this.onDrag);
      window.removeEventListener('mouseup', this.stopDragging);
    },
  },
};
  </script>
  
  <style scoped>
.box {
  width: 100%;
  height: 50px;
  position: relative;
}
.scale-container {
  position: absolute;
  left: 15px;
  width: 95%;
  height: 50px;
  display: flex;
  align-items: center;
}

.scale-bar {
  position: absolute;
  top: 50%;
  left: 0;
  width: 100%;
  height: 14px;
  background: linear-gradient(to right, #EB3770, #FEB607, #4ce34c, #FEB607, #EB3770);
  transform: translateY(-50%);
}

.marker {
  position: absolute;
  top: 50%;
  height: 14px;
  width: 30px;
  /* background-color: #83f766; */
  color: #fff !important;
  text-align: center;
  line-height: 14px;
  /* border-radius: 10px; */
  transform: translate(-50%, -50%);
  cursor: pointer;
  user-select: none; /* 防止文本选择 */
  -webkit-user-select: none; /* Safari */
  -moz-user-select: none; /* Firefox */
  -ms-user-select: none; /* Internet Explorer/Edge */
}
.marker2 {
  position: absolute;
  top: 50%;
  height: 14px;
  width: 30px;
  /* background-color: red; */
  color: #fff;
  text-align: center;
  line-height: 14px;
  /* border-radius: 10px; */
  transform: translate(-50%, -50%);
  cursor: pointer;
  user-select: none; /* 防止文本选择 */
  -webkit-user-select: none; /* Safari */
  -moz-user-select: none; /* Firefox */
  -ms-user-select: none; /* Internet Explorer/Edge */
}
.marker::before, .marker2::before {
  content: '';
  position: absolute;
  top: -7.5px;
  left: 50%;
  transform: translateX(-50%);
  width: 0;
  height: 0;
  border-left: 7.5px solid transparent;
  border-right: 7.5px solid transparent;
  border-top: 7.5px solid #000;
}
.scale-number {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  color: #000;
}

.left {
  left: 0;
}

.right {
  right: 0;
}
</style>