<!-- 方案 -->
<template>
  <div class="app-container">
    <div class="serch">
      <el-form :model="queryParams" ref="queryForm" size="small" :inline="true" v-show="showSearch" label-width="120px">
        <el-form-item label="诊断方案名称" prop="diagnosticName">
          <el-input v-model="queryParams.name" placeholder="请输入诊断方案名称" clearable @keyup.enter.native="handleQuery" />
        </el-form-item>
        <el-form-item>
          <el-button type="primary" icon="el-icon-search" size="mini" @click="handleQuery">搜索</el-button>
          <el-button icon="el-icon-refresh" size="mini" @click="resetQuery">重置</el-button>
          <el-button type="primary" plain icon="el-icon-plus" size="mini" @click="handleAdd">新增</el-button>
          <el-button type="danger" plain icon="el-icon-delete" size="mini" :disabled="multiple" @click="handleDelete">删除</el-button>
        </el-form-item>
      </el-form>
    </div>
    <!-- <el-row :gutter="10" class="mb8">
      <el-col :span="1.5">
        <el-button type="primary" plain icon="el-icon-plus" size="mini" @click="handleAdd">新增</el-button>
      </el-col>
      <el-col :span="1.5">
        <el-button type="danger" plain icon="el-icon-delete" size="mini" :disabled="multiple" @click="handleDelete">删除</el-button>
      </el-col>
    </el-row> -->

    <div class="table">
      <div class="jia_table">
        <el-table v-loading="loading" :data="schemeList" @selection-change="handleSelectionChange" style="width: 100%" height="95%" :header-cell-style="{ background: '#f9fbff',height:'48.5px',fontSize:'14px' }">
          <el-table-column type="selection" width="55" />
          <!-- <el-table-column label="主键ID"  prop="id" /> -->
          <el-table-column label="序号" type="index" width="100" :index="indexMethod" />
          <el-table-column label="方案名称" prop="name" />
          <el-table-column label="运行状态" prop="scheduled_status" />
          <el-table-column label="时间类型" prop="time_type">
            <template slot-scope="scope">
              {{ findEngishName(scope.row.time_type) }}
            </template>
          </el-table-column>
          <el-table-column label="时间间隔" prop="interval_seconds" />
          <el-table-column label="创建时间" prop="create_time" width="200" />
          <el-table-column label="描述信息" prop="scheduled_concent" />
          <el-table-column label="操作" class-name="small-padding fixed-width" fixed="right" width="180">
            <template slot-scope="scope">
              <el-button size="mini" type="text" icon="el-icon-edit" @click="handleUpdate(scope.row)">修改</el-button>
              <el-button size="mini" type="text" icon="el-icon-delete" @click="handleDelete(scope.row)">删除</el-button>
            </template>
          </el-table-column>
        </el-table>
        <!-- 如果没有数据，显示空状态 -->
        <el-empty v-if="schemeList.length === 0" image="/static/img/home/placeholder_kong.png" :image-size="307" description="暂时没有数据~"></el-empty>
      </div>

      <!-- <pagination v-show="total > 0" :total="total" :page.sync="queryParams.page" :limit.sync="queryParams.per_page" @pagination="getList" /> -->
      <div class="page">
        <el-pagination v-show="total > 0" :total="total" :current-page.sync="queryParams.page" :page-size.sync="queryParams.per_page" layout="total, prev, pager, next, jumper,sizes" @current-change="getList" @size-change="getList" />
      </div>
    </div>
    <!-- 添加或修改【请填写功能名称】对话框 -->
    <el-dialog :title="title" :visible.sync="open" width="1000px" append-to-body>
      <el-form ref="form" :model="form" :rules="rules" label-width="170px" class="jia_form" :inline="true" label-position="top">
        <el-form-item label="任务名称" prop="name">
          <el-input v-model="form.name" placeholder="请输入任务名称" />
        </el-form-item>
        <el-form-item label="任务间隔时间" prop="interval_seconds">
          <el-input v-model="form.interval_seconds" placeholder="请输入任务间隔时间">
            <template #append>
              {{ intervalUnit }}
            </template>
          </el-input>
        </el-form-item>
        <el-form-item label="时间类型" prop="time_type">
          <el-select v-model="form.time_type" placeholder="请选择时间类型" size="small" clearable filterable>
            <el-option v-for="item in timeOptions" :key="item.value" :label="item.label" :value="item.value"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="是否启用" prop="scheduled_status">
          <el-select v-model="form.scheduled_status" placeholder="请选择是否启用" size="small" clearable filterable>
            <el-option v-for="item in scheduledOptions" :key="item.value" :label="item.label" :value="item.value"> </el-option>
          </el-select>
        </el-form-item>
        <el-form-item label="备注" prop="scheduled_concent">
          <el-input v-model="form.scheduled_concent" type="textarea" placeholder="请输入备注" style="width: 460px;" />
        </el-form-item>
        <br />

        <div class="jia_boxF">
          <div class="jia_left">
            <el-checkbox :indeterminate="isIndeterminate" v-model="checkAll" @change="handleCheckAllChange" style="width: 100%;height: 50px;display: flex;flex-wrap: nowrap;align-items: center;">全选</el-checkbox>
            <el-checkbox-group v-model="checkedList" @change="handleCheckedCitiesChange">
              <div class="jia_box" v-for="(item) in diagnosis_type_list" :key="item.id+item.name">
                <el-checkbox class="jia_checkbox" :label="item.name" style="height: 50px;display: flex;flex-wrap: nowrap;align-items: center;">
                  <div class="jia_title">
                    {{item.name}}
                  </div>
                </el-checkbox>

              </div>
            </el-checkbox-group>
          </div>
          <div class="jia_right">
            <div class="jia_value" v-for="(item,index) in diagnosis_type_list" :key="item.id+item.name+'sss'">
              <ScaleSlider :initialMarker1Value="Number(item.prewarn)" :initialMarker2Value='Number(item.warn)' @updateMarkers="(updatedValues) => handleUpdateMarkers(index, updatedValues)"></ScaleSlider>
            </div>
          </div>

        </div>
        <!-- 此处br为了防止与上面重复 -->
        <br />
        <div class="content_right">
          <div class="monitorF">
            <div class="child" @click="getMonitorListFind('全部监控点')">全部监控点</div>
            <!-- <div class="child" v-for="(item,index) in monitorF" :key="index+item" @click="getMonitorListFind(item)">{{index}}--{{ item }}</div>
              -->
            <!-- <el-select v-model="selectedMonitor" @change="getMonitorListFind" placeholder="请选择监控项" size="small">
              <el-option v-for="(item, index) in monitorF" :key="index + item" :label="item" :value="item">
              </el-option>
            </el-select> -->
          </div>
          <br/>
          <div style="text-align: center">
            <div class="transferTreeBox">
              <div class="SelectBox">
                <div class="boxTitle" @click="clickAllSelect">未配置监控点 &gt;</div>
                <div class="boxCenter">
                  <el-tree
                    ref="leftTree"
                    :data="leftData"
                    :props="defaultProps"
                    show-checkbox
                    node-key="id"
                  />
                </div>
              </div>
              <div class="transferBtn">
                <el-button type="primary" size="small" @click="towardsLeft"> <i class="el-icon-arrow-left"></i> 移除</el-button>
                <el-button type="primary" size="small" @click="towardsRight">添加<i class="el-icon-arrow-right"></i></el-button>
              </div>
              <div class="SelectBox">
                <div class="boxTitle" @click="clickCancelAllSelect">已配置选中监控点</div>

                <div class="boxCenter">
                  <el-tree
                    ref="rightTree"
                    :data="rightData"
                    :props="defaultProps"
                    show-checkbox
                    node-key="id"
                  />
                </div>
              </div>
            </div>
            <!-- <el-transfer style="text-align: left; display: inline-block" v-model="monitorValue" filterable :left-default-checked="[2, 3]" :right-default-checked="[1]" :titles="['未配置监控点', '已配置选中监控点']" :button-texts="['移除', '添加']" :format="{
                  noChecked: '${total}',
                  hasChecked: '${checked}/${total}'
                }" :data="monitorData" @change="handleChange">
            </el-transfer> -->
          </div>
        </div>
      </el-form>
      <br />
      <br />
      <br />
      <br />
      <div slot="footer" class="dialog-footer">
        <el-button type="primary" @click="submitForm">确 定</el-button>
        <el-button @click="cancel">取 消</el-button>
      </div>
    </el-dialog>
  </div>
</template>
  
  <script>
// import { listScheme, getScheme, delScheme, addScheme, updateScheme } from "@/api/zdzh/scheme";

import ScaleSlider from "./ScaleSlider.vue"
// import ScaleSlider from "../../../components/spzlzd/ScaleSlider.vue"

export default {
  name: "Scheme",
  components: {
    ScaleSlider,
  },
  data() {
    return {
      // 遮罩层
      loading: false,
      // 选中数组
      ids: [],
      // 非单个禁用
      single: true,
      // 非多个禁用
      multiple: true,
      // 显示搜索条件
      showSearch: true,
      // 总条数
      total: 0,
      // 【请填写功能名称】表格数据
      schemeList: [],
      // 弹出层标题
      title: "",
      // 是否显示弹出层
      open: false,
      // 查询参数
      queryParams: {
        per_page: 10,
        page: 1,
        time_type: '',
        scheduled_status: ''
      },
      // 表单参数
      form: {

      },
      // 表单校验
      rules: {
        name: [
          { required: true, message: '此项为必填', trigger: 'blur' }
        ],
        time_type: [
          { required: true, message: '此项为必填', trigger: 'change' }
        ],
        interval_seconds: [
          { required: true, message: '此项为必填', trigger: 'blur' },
          { pattern: /^[1-9]\d*$/, message: '请输入有效的正整数' }
        ],
        scheduled_status: [{ required: true, message: '此项为必填', trigger: 'change' }],
      },
      algorithmOptions: [],
      diagnosis_type_list: [],
      timeOptions: [
        // 'weeks',//(int) – 间隔几周
        // 'days',//(int) – 间隔几天
        // 'hours',//(int) – 间隔几小时
        // 'minutes',//(int) – 间隔几分钟
        // 'seconds',//(int) – 间隔多少秒
        {
          value: 'days',
          label: '天'
        },
        {
          value: 'weeks',
          label: '周'
        },
        {
          value: 'months',
          label: '月'
        },

        // {
        //   value: 'hours',
        //   label: '时'
        // },
        // {
        //   value: 'minutes',
        //   label: '分'
        // },
        // {
        //   value: 'seconds',
        //   label: '秒'
        // },
      ],
      scheduledOptions: [
        {
          value: 1,
          label: '启用'
        },
        {
          value: 0,
          label: '禁用'
        },
      ],
      checkAll: false,//选中所有
      isIndeterminate: false,
      checkedList: [],//已选中数据
      monitorData: [],//所有监控点
      monitorValue: [],//当前选中的监控点
      monitorF: [],//录像机
      selectedMonitor: '', // 用来绑定选中的值
      
      defaultProps: {
        children: 'children',
        label: 'equipment_name',
      },
      leftData: [],
      rightData: [],
      mockTreeData:[]
    };
  },
  computed: {
    intervalUnit() {
      // 根据选中的时间类型返回相应的单位
      switch (this.form.time_type) {
        case 'seconds':
          return '秒';
        case 'minutes':
          return '分钟';
        case 'hours':
          return '小时';
        case 'days':
          return '天';
        case 'weeks':
          return '周';
        case 'months':
          return '月';
        default:
          return '';
      }
    }
  },
  created() {
    this.getDict();
    this.getList();
    this.getMonitorList();
    // this.rightData = []
  },
  methods: {
    
    // 点击向右穿梭
    towardsRight() {
      // (leafOnly, includeHalfChecked) 接收两个 boolean 类型的参数，
      // 1. 是否只是叶子节点，默认值为 false 2. 是否包含半选节点，默认值为 false
      const checkedNodes = this.$refs.leftTree.getCheckedNodes(false, true) // 包含半选
      const checkedKeys = this.$refs.leftTree.getCheckedKeys(false)

      const copyNodes = JSON.parse(JSON.stringify(checkedNodes))
      copyNodes.forEach(x => {
        x.children = []
        if (!this.$refs.rightTree.getNode(x.id)) {
          this.$refs.rightTree.append(x, x.parent_id)
        }
      })

      checkedKeys.forEach(x => {
        this.$refs.leftTree.remove(x)
      })
      this.afterToward()
    },
    // 点击向左穿梭
    towardsLeft() {
      const checkedNodes = this.$refs.rightTree.getCheckedNodes(false, true) // 包含半选
      const checkedKeys = this.$refs.rightTree.getCheckedKeys(false)

      const copyNodes = JSON.parse(JSON.stringify(checkedNodes))
      copyNodes.forEach(x => {
        x.children = []
        if (!this.$refs.leftTree.getNode(x.id)) {
          this.$refs.leftTree.append(x, x.parent_id)
        }
      })

      checkedKeys.forEach(x => {
        this.$refs.rightTree.remove(x)
      })

      this.afterToward()
    },
    // 点击全选
    clickAllSelect() {
      this.$refs.leftTree.setCheckedNodes(this.leftData)

      this.towardsRight()
    },
    // 点击取消全选
    clickCancelAllSelect() {
      this.$refs.rightTree.setCheckedNodes(this.rightData)
      this.towardsLeft()
    },
    // 数据穿梭后
    afterToward() {
      this.$refs.leftTree.setCheckedKeys([])
      this.$refs.rightTree.setCheckedKeys([])
      console.log(this.leftData, this.rightData)
      this.$emit('getData', {
        leftData: this.leftData,
        rightData: this.rightData,
      })
    },
    // 数据回显
    renderTree() {
      this.leftData = [mockTreeData[1]]
      this.rightData = [mockTreeData[0], mockTreeData[2]]
    },
    findEngishName(en) {
      let res = this.timeOptions.find(v => v.value == en)
      return res ? res.label : en
    },
    /* 获取字典数据 */
    getDict() {
      this.$http
        .get(
          this.$url.url_5000 + "/model_view/type_select",
          {
            // params: {
            //   mine_id: this.mkname,
            // },
          },
          {
            withCredentials: true,
          }
        )
        .then((response) => {
          // console.log(response);
          // if (response.data.code === 200) {
          //   this.options1 = response.data.mine_list;
          //   this.options2 = response.data.equipment_list;
          //   this.options3 = response.data.type_list;
          //   this.options4 = response.data.algorithm_list;
          // this.algorithmOptions=[];//强行重新赋值用于加载数据
          this.algorithmOptions = response.data.diagnosis_type_result;
          // console.log(this.algorithmOptions);
          // }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    getDict2() {
      this.$http
        .get(
          this.$url.url_5000 + "/model_view/type_select",
          {
            // params: {
            //   mine_id: this.mkname,
            // },
          },
          {
            withCredentials: true,
          }
        )
        .then((response) => {
          this.diagnosis_type_list = response.data.diagnosis_type_result;
          // console.log("0000000",this.diagnosis_type_list);
          // return response.data.diagnosis_type_result
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    handleUpdateMarkers(index, { marker1Value, marker2Value }) {
      this.diagnosis_type_list[index].prewarn = marker1Value;
      this.diagnosis_type_list[index].warn = marker2Value;
    },
    /** 查询【请填写功能名称】列表 */
    getList() {
      this.loading = true;
      // listScheme(this.queryParams).then(response => {
      //   console.log(response);
      //   this.schemeList = response.rows;
      //   this.total = response.total;
      //   this.loading = false;
      // });
      this.$http
        .get(
          this.$url.url_5000 + "/scheduler_task/show_task",
          {
            params: {
              ...this.queryParams
            },
          },
          {
            withCredentials: true,
          }
        )
        .then((response) => {
          this.schemeList = response.data.data.data;
          this.total = response.data.data.total_items;
          this.loading = false;
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    // 取消按钮
    cancel() {
      this.open = false;
      this.reset();
      this.checkAll = false
      this.isIndeterminate = false
      this.checkedList = []
    },
    // 表单重置
    reset() {
      this.form = {
        id: null,
      };
      // this.resetForm("form");
    },
    /** 搜索按钮操作 */
    handleQuery() {
      this.queryParams.page_num = 1;
      this.getList();
    },
    /** 重置按钮操作 */
    resetQuery() {
      // this.resetForm("queryForm");
      this.handleQuery();
    },
    // 多选框选中数据
    handleSelectionChange(selection) {
      this.ids = selection.map(item => item.id)
      this.single = selection.length !== 1
      this.multiple = !selection.length
    },
    /** 新增按钮操作 */
    handleAdd() {
      this.diagnosis_type_list = []
      this.getDict2();
      this.checkAll = false
      this.isIndeterminate = false
      // this.checkedList = []
      this.$set(this.checkedList, [])
      this.reset();
      this.rightData=[]
      this.open = true;
      this.title = "添加方案配置";
    },
    /** 修改按钮操作 */
    handleUpdate(row) {
      this.checkAll = false
      this.isIndeterminate = false
      this.$set(this.checkedList, [])
      // this.checkedList = []
      this.reset();
      // 创建一个新的 FormData 对象
      // const formData = new FormData();
      // let form = {
      //   id: row.id
      // }
      // Object.keys(form).forEach(key => {
      //   formData.append(key, form[key]);
      // });
      // console.log(row);
      this.$http
        .get(
          this.$url.url_5000 + "/scheduler_task/task_detail",
          {
            params: {
              id: row.id
            }
          }
        )
        .then((response) => {
          let res = response.data.data
          this.form = res
          this.form.scheduled_status = res.scheduled_status == '启用' ? 1 : 0
          let arr = [...this.algorithmOptions]
          let arr2 = res.diagnosis_type_list
          // 遍历小数组中的每一个元素
          arr2.forEach(smallItem => {
            this.checkedList.push(smallItem.name)
            // 在大数组中查找id相同的元素
            let index = arr.findIndex(bigItem => bigItem.id === smallItem.id);

            if (index !== -1) {
              // 如果找到了匹配的元素，则替换它
              arr[index] = {
                ...arr[index], // 保留原有的属性
                prewarn: smallItem.prewarn_threshold,       // 更新需要改变的属性
                warn: smallItem.warn_threshold,       // 更新需要改变的属性
              };
            }
          });
          this.diagnosis_type_list = arr

          //处理监控点
          this.rightData = res.rtsp_list
          // let monitor = res.rtsp_list
          // monitor.forEach((v => {
          //   this.monitorValue.push(v.id)
          // }))
          this.rightData.forEach(x => {
            if(x.children){
              x.children.forEach(s => {
                this.jkdfn(this.leftData, s.equipment_name);
              })
            }
          })
          // this.jkdfn()
          this.open = true
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    jkdfn(nodes, nodeLabel){
      for (let i = 0; i < nodes.length; i++) {
        if (nodes[i].equipment_name === nodeLabel) {
          nodes.splice(i, 1); // 从数组中移除节点
          return true; // 找到并删除节点，返回true
        } else if (nodes[i].children && nodes[i].children.length > 0) {
          if (this.jkdfn(nodes[i].children, nodeLabel)) { // 递归调用以查找子节点中的目标节点
            return true; // 如果在子节点中找到并删除，返回true
          }
        }
      }
      return false; // 没有找到节点，返回false
      // this.rightData.forEach(x => {
      //   var index = this.leftData.indexOf(x);
      //   if (index !== -1) {
      //     this.leftData.splice(index, 1);
      //   }
      // })
    },
    /** 提交按钮 */
    submitForm() {
      this.$refs["form"].validate(valid => {
        if (valid) {
          // let rtsp_list = this.findCamerasById(this.monitorData, this.monitorValue)
          let rtsp_list = this.rightData
          let diagnosis_type_list = this.findCheckedByName(this.diagnosis_type_list, this.checkedList)
          this.form.rtsp_list = JSON.stringify(rtsp_list)
          this.form.diagnosis_type_list = JSON.stringify(diagnosis_type_list)
          if (this.form.id != null) {
            this.form.scheduled_status = this.form.scheduled_status == 1 ? '启用' : '禁用'
          }
          // 创建一个新的 FormData 对象
          const formData = new FormData();
          Object.keys(this.form).forEach(key => {
            formData.append(key, this.form[key]);
          });

          if (this.form.id != null) {//修改
            this.$http.post(
              this.$url.url_5000 + "/scheduler_task/update_task",
              formData,
              {
                headers: {
                  "Content-Type": "multipart/form-data",
                },
              }
            ).then(response => {
              this.$message(
                {
                  type: 'success',
                  message: response.data.msg
                }
              )
              this.open = false;
              this.getList();
            }).catch(rek => {
              this.$message(
                {
                  type: 'error',
                  message: rek.data.msg
                }
              )
            })
          } else {
            this.$http.post(
              this.$url.url_5000 + "/scheduler_task/add_task",
              formData,
              {
                headers: {
                  "Content-Type": "multipart/form-data",
                },
              }
            ).then(response => {
              this.$message(
                {
                  type: 'success',
                  message: response.data.msg
                }
              )
              this.open = false;
              this.getList();
            }).catch(rek => {
              this.$message(
                {
                  type: 'error',
                  message: rek.data.msg
                }
              )
            })
          }
        }
      });
    },
    findCamerasById(cameras, idsToFind) {
      // 使用 filter 方法过滤出符合条件的摄像头信息
      let result = cameras.filter(camera => idsToFind.includes(camera.id));

      // 对结果进行处理，去除 key 和 label 字段
      result = result.map((camera) => {
        return {
          id: camera.id,
          ip: camera.ip,
          name: camera.name,
          parent_ip: camera.parent_ip,
          rtsp: camera.rtsp,
        };
      });

      return result;
    },
    findCheckedByName(checkAllList, checkedList) {
      // 使用 filter 方法过滤出符合条件的摄像头信息
      let result = checkAllList.filter(camera => checkedList.includes(camera.name));
      // 对结果进行处理，去除 key 和 label 字段
      result = result.map(v => {
        return {
          id: v.id,
          name: v.name,
          prewarn_threshold: v.prewarn,
          warn_threshold: v.warn
        }
      });

      return result;
    },
    /** 删除按钮操作 */
    handleDelete(row) {
      const ids = row.id ? JSON.stringify([row.id]) : null || JSON.stringify(this.ids);
      this.$confirm('是否确认删除编号为"' + ids + '"的数据项？').then(() => {
        // return delScheme(ids);
        const formData = new FormData();
        let form = { id: ids }
        Object.keys(form).forEach(key => {
          formData.append(key, form[key]);
        });
        this.$http.post(
          this.$url.url_5000 + "/scheduler_task/delete_task",
          formData,
          {
            headers: {
              "Content-Type": "multipart/form-data",
            },
          }
        )
          .then(response => {
            this.getList();
            // this.$modal.msgSuccess("删除成功");
            this.$message(
              {
                type: 'success',
                message: '删除成功'
              }
            )
          })
        // .catch(rek => {
        //   this.$message(
        //     {
        //       type: 'error',
        //       message: rek.data.msg
        //     }
        //   )
        // })
      }).then(() => {
        this.getList();
      }).catch(() => {
        this.$message(
          {
            type: 'info',
            message: '取消删除'
          }
        )
      });
    },
    /** 导出按钮操作 */
    handleExport() {
      this.download('riskManage/scheme/export', {
        ...this.queryParams
      }, `scheme_${new Date().getTime()}.xlsx`)
    },
    getValue(row, column, cellValue) {
      if (cellValue != null) {
        return 0 + '~' + cellValue
      }
    },
    getValue1(row, column, cellValue) {
      if (cellValue != null) {
        return cellValue + '~' + 100
      }

    },
    indexMethod(index) {
      return ((this.queryParams.page - 1) * this.queryParams.per_page + 1) + index
    },
    handleCheckAllChange(val) {
      this.checkedList = val ? this.diagnosis_type_list.map(v => v.name) : [];
      this.isIndeterminate = false;
    },
    handleCheckedCitiesChange(value) {
      let checkedCount = value.length;
      this.checkAll = checkedCount === this.diagnosis_type_list.length;
      this.isIndeterminate = checkedCount > 0 && checkedCount < this.diagnosis_type_list.length;
    },
    // 获取监控点列表
    getMonitorList() {
      this.$http
        .get(this.$url.url_5000 + "/model_view/equipment_show", {
          params: {
            equipment_name: '',
            equipment_type: '',
            page: 1,
            per_page: 99999999,
          },
        })
        .then((response) => {
          this.mockTreeData = response.data.data_list.data;
          this.leftData = this.mockTreeData
          let res = response.data.data_list.data
          res.forEach((v) => {
            this.monitorF.push(v.equipment_name)
            if (v.children) {
              v.children.forEach(k => {
                let msg = {
                  key: k.id,
                  label: k.equipment_name,
                  ip: k.equipment_ip,
                  parent_ip: k.parent_ip,
                  rtsp: k.rtsp,
                  id: k.id,
                  name: k.equipment_name,
                }
                this.monitorData.push(msg)
              })
            }
          })
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    getMonitorListFind() {
      let name = this.selectedMonitor
      this.monitorData = []
      this.monitorValue = []
      this.$http
        .get(this.$url.url_5000 + "/model_view/equipment_show", {
          params: {
            equipment_name: '',
            equipment_type: '',
            page: 1,
            per_page: 99999999,
          },
        })
        .then((response) => {
          let res = response.data.data_list.data
          if (name == '全部监控点') {
            res.forEach((v) => {
              if (v.children) {
                v.children.forEach(k => {
                  let msg = {
                    key: k.id,
                    label: k.equipment_name,
                    ip: k.equipment_ip,
                    parent_ip: k.parent_ip,
                    rtsp: k.rtsp,
                    id: k.id,
                    name: k.equipment_name,
                  }
                  this.monitorData.push(msg)
                })
              }
            })
          } else {
            res.forEach((v) => {
              if (v.equipment_name == name) {
                if (v.children) {
                  v.children.forEach(k => {
                    let msg = {
                      key: k.id,
                      label: k.equipment_name,
                      ip: k.equipment_ip,
                      parent_ip: k.parent_ip,
                      rtsp: k.rtsp,
                      id: k.id,
                      name: k.equipment_name,
                    }
                    this.monitorData.push(msg)
                  })
                }
              }
            })
          }
        })
        .catch(function (response) {
          console.log(response);
        });
    },
    handleChange() {//穿梭框变化触发的函数

    },

  }
};
